// 2007:0A4D: uint16 DetermineOctant_0A4D(int16 deltaY, int16 deltaX)
uint16 DetermineOctant_0A4D(int16 deltaY, int16 deltaX)
{
	if (deltaY < 0x00)
	{
		if (deltaX > 0x00)
			return (-deltaY > deltaX) ? 0x03 : 0x02;
		return (-deltaX > -deltaY) ? 0x05 : 0x04;
	}

	if (deltaX > 0x00)
		return (deltaX > deltaY) ? 0x01 : 0x00;

	return (-deltaX < deltaY) ? 0x07 : 0x06;
}

// 2007:0D90: uint16 CalculateApproximateMapDistance_0D90(
//     Stack int16 sourceX, Stack int16 sourceY,
//     Stack int16 targetX, Stack int16 targetY)
// Called from:
//      ResolveWeaponAttack_1854
uint16 CalculateApproximateMapDistance_0D90(
	int16 sourceX,
	int16 sourceY,
	int16 targetX,
	int16 targetY)
{
	// V: integer octile-distance approximation used by weapon range checks:
	// the larger axis delta plus half of the smaller axis delta.
	uint16 deltaX = sourceX >= targetX
		? (uint16) (sourceX - targetX)
		: (uint16) (targetX - sourceX);
	uint16 deltaY = sourceY >= targetY
		? (uint16) (sourceY - targetY)
		: (uint16) (targetY - sourceY);

	return deltaX > deltaY
		? deltaX + (deltaY >> 0x01)
		: deltaY + (deltaX >> 0x01);
}

